toad_implementation.code_blueprint:
canvas {
  size: 800px 1050px;
  fill: #120A0E;
  font-family: "Cormorant Infant, serif";
}

>velvet = #120A0E;
>antiqueIvory = #E8D8B8;
>crimson = #8C1D2F;
>stageGold = #B89758;

rect #stageFrame {
  at: center of canvas;
  size: 700px 950px;
  fill: #190F14;
  stroke: >stageGold;
  stroke-width: 1px;
}

circle #spotlightGlow {
  at: top center of #stageFrame offset 0px 180px;
  size: 400px;
  fill: alpha(>antiqueIvory, 0.25);
}

text #operaTitle {
  at: top center of #stageFrame offset 0px 160px;
  content: "T O S C A";
  font-size: 76px;
  font-weight: 300;
  color: >antiqueIvory;
}

text #composer {
  at: below #operaTitle offset 16px;
  content: "GIACOMO PUCCINI • DRAMMA IN TRE ATTI";
  font-size: 13px;
  font-weight: 600;
  color: >stageGold;
}

rect #dividerLine {
  at: below #composer offset 40px;
  size: 180px 1px;
  fill: >stageGold;
}

text #leadCast {
  at: below #dividerLine offset 60px;
  size: 500px;
  content: "MUSIKALISCHE LEITUNG: RICCARDO CHAILLY\nINSZENIERUNG: DAVID LYNCH\nORCHESTER DER WIENER STAATSOPER";
  font-size: 14px;
  color: >antiqueIvory;
}

text #performanceDates {
  at: bottom center of #stageFrame offset 0px -48px;
  content: "PREMIERE: 15. DEZEMBER 2026";
  font-size: 12px;
  font-weight: 600;
  color: >stageGold;
}
